import { z } from 'zod'

export const SlugSchema = z.string().regex(/^[a-z0-9][a-z0-9_-]{0,63}$/)

export const ScopeSchema = z.discriminatedUnion('kind', [
  z.object({ kind: z.literal('all') }),
  z.object({ kind: z.literal('groups'),  groups:  z.array(SlugSchema).min(1).max(64) }),
  z.object({ kind: z.literal('servers'), servers: z.array(SlugSchema).min(1).max(64) }),
])
export type Scope = z.infer<typeof ScopeSchema>

export const GrantSchema = z.object({
  scope:  ScopeSchema,
  invoke: z.boolean(),        // false = may list tools, may not call them
  smart:  z.boolean().default(true), // may use the $smart meta-tool route
})
export type Grant = z.infer<typeof GrantSchema>

/** Anything malformed, absent, or unparseable resolves to this. Never to FULL. */
export const DENY: Grant  = { scope: { kind: 'servers', servers: [] }, invoke: false, smart: false }
export const FULL: Grant  = { scope: { kind: 'all' }, invoke: true, smart: true }

export type Principal =
  | { via: 'session'; userId: string; admin: boolean; grant: Grant; credentialId: null }
  | { via: 'apikey' | 'oauth'; userId: string; admin: false; grant: Grant; credentialId: string }

/** Migrations, the embedding sync worker, the keepalive loop. Grep-able, 3 call sites. */
export const systemPrincipal = (): Principal =>
  ({ via: 'session', userId: 'system', admin: true, grant: FULL, credentialId: null })

// ponytail: `smart` is a third boolean on Grant rather than a capability list;
// ceiling = one more meta-capability. Upgrade path: swap the two booleans for
// `caps: ('list'|'invoke'|'smart')[]` — one zod line, one call site in authz.ts.

/** @param members slug -> server slugs in that group (already loaded) */
export function intersectScope(
  route: Scope,
  grant: Scope,
  members: (group: string) => string[],
): Scope | null {
  const expand = (s: Scope): string[] | '*' =>
    s.kind === 'all' ? '*'
    : s.kind === 'servers' ? s.servers
    : s.groups.flatMap(members)

  const allowed = expand(grant)
  if (allowed === '*') return route            // unscoped key: route wins verbatim

  const wanted = expand(route)
  if (wanted === '*') {
    // route = /mcp (everything) but the key is scoped: narrow, do not deny.
    return grant
  }
  // CONTAINMENT, not intersection: a partially-satisfiable route is a denial.
  const set = new Set(allowed)
  return wanted.every(s => set.has(s)) ? route : null
}

/** Unambiguous route grammar. mcphub's `:group` slot tries group-name ->
 *  group-UUID -> SERVER-name -> all (mcpService.ts:4811), so a server named
 *  like a group silently shadows it. Ours cannot collide. */
export function parseRouteScope(pathname: string): { scope: Scope; smart: boolean } | null {
  // /mcp | /mcp/smart | /mcp/g/<slug> | /mcp/s/<slug> | /mcp/smart/g/<slug>
  const m = /^\/mcp(?:\/(smart))?(?:\/(g|s)\/([a-z0-9][a-z0-9_-]{0,63}))?$/.exec(pathname)
  if (!m) return null
  const [, smart, kind, slug] = m
  const scope: Scope = !kind ? { kind: 'all' }
    : kind === 'g' ? { kind: 'groups', groups: [slug!] }
    : { kind: 'servers', servers: [slug!] }
  return { scope, smart: Boolean(smart) }
}

import { auth } from './betterAuth.js'
import { GrantSchema, DENY, FULL, type Principal, parseRouteScope } from '@mcpr/core'

export type AuthResult =
  | { ok: true; principal: Principal }
  | { ok: false; status: 401 | 403; wwwAuthenticate?: string; error?: string }

const challenge = (resource: string, scope = 'mcp:invoke') =>
  `Bearer resource_metadata="${resource}", scope="${scope}"`

export async function authenticate(req: Request): Promise<AuthResult> {
  const h = req.headers.get('authorization') ?? ''
  const bearer = h.startsWith('Bearer ') ? h.slice(7).trim() : null
  const prm = new URL('/.well-known/oauth-protected-resource/mcp', req.url).href

  if (bearer?.startsWith('mcpr_')) {
    const { valid, key } = await auth.api.verifyApiKey({ body: { key: bearer } })
    if (!valid || !key) return { ok: false, status: 401, wwwAuthenticate: challenge(prm) }
    const parsed = GrantSchema.safeParse((key.metadata as any)?.grant)
    // Fail CLOSED. A key whose metadata was tampered with authorizes nothing.
    const grant = parsed.success ? parsed.data : DENY
    return { ok: true, principal:
      { via: 'apikey', userId: key.userId, admin: false, grant, credentialId: key.id } }
  }

  if (bearer) {
    const t = await auth.api.getMcpSession({ headers: req.headers })   // mcp plugin, stateless
    if (!t) return { ok: false, status: 401, wwwAuthenticate: challenge(prm) }
    // RFC 8707: the token's audience IS its scope. No custom per-group scope strings.
    const aud = parseRouteScope(new URL(t.resource).pathname)
    if (!aud) return { ok: false, status: 403, error: 'insufficient_scope' }
    return { ok: true, principal: { via: 'oauth', userId: t.userId, admin: false,
      grant: { scope: aud.scope, invoke: t.scopes.includes('mcp:invoke'), smart: aud.smart },
      credentialId: t.tokenId } }
  }

  const s = await auth.api.getSession({ headers: req.headers })
  if (!s) return { ok: false, status: 401, wwwAuthenticate: challenge(prm) }
  return { ok: true, principal: { via: 'session', userId: s.user.id,
    admin: (s.user as { role?: string }).role === 'admin', grant: FULL, credentialId: null } }
}

/** Hono middleware. The ONE place runWithContext is called for HTTP. */
export const requireAuth = createMiddleware(async (c, next) => {
  const r = await authenticate(c.req.raw)
  if (!r.ok) {
    if (r.wwwAuthenticate) c.header('WWW-Authenticate', r.wwwAuthenticate)
    return c.json({ error: r.error ?? 'unauthorized' }, r.status)
  }
  c.set('principal', r.principal)
  // principal in ALS is for log/audit correlation ONLY — authz takes it as a param.
  return runWithContext({ principal: r.principal, requestId: c.get('requestId') }, next)
})

export const requireAdmin = createMiddleware(async (c, next) =>
  c.get('principal').admin ? next() : c.json({ error: 'forbidden' }, 403))

// ---- authz.ts : the only authorization code in the repo ----
export type Action = 'discover' | 'invoke' | 'manage'
type Scoped = typeof servers | typeof groups   // both have id, slug, ownerId, visibility

export function visibleTo(p: Principal, action: Action, t: Scoped): SQL {
  if (action === 'invoke' && !p.grant.invoke) return sql`false`
  if (p.admin) return sql`true`
  const mine = eq(t.ownerId, p.userId)
  if (action === 'manage') return mine        // config read/write: owner or admin, period
  const shared = exists(raw.select({ x: sql`1` }).from(resourceShare).where(and(
    eq(resourceShare.resourceId, t.id), eq(resourceShare.userId, p.userId))))
  return or(mine, eq(t.visibility, 'public'),
            and(eq(t.visibility, 'shared'), shared))!
}

/** Grant scope pushed into SQL. Exported so smart-routing composes it INTO the
 *  pgvector query rather than filtering after LIMIT. */
export function grantFilter(g: Grant, t: Scoped): SQL {
  switch (g.scope.kind) {
    case 'all':     return sql`true`
    case 'servers': return t === servers ? inArray(t.slug, g.scope.servers)
                                         : sql`false`
    case 'groups':  return t === groups
      ? inArray(t.slug, g.scope.groups)
      : exists(raw.select({ x: sql`1` }).from(groupServer).innerJoin(groups,
          eq(groupServer.groupId, groups.id)).where(and(
            eq(groupServer.serverId, t.id), inArray(groups.slug, g.scope.groups))))
  }
}

export const gate = (p: Principal, a: Action, t: Scoped): SQL =>
  and(visibleTo(p, a, t), grantFilter(p.grant, t))!

