const raw = drizzle(pool, { schema })   // NOT EXPORTED. Not in the exports map.

export function scoped(p: Principal) {
  return {
    servers: {
      list:   (a: Action = 'discover') => raw.select().from(servers).where(gate(p, a, servers)),
      get:    (slug: string, a: Action = 'discover') => raw.select().from(servers)
                 .where(and(eq(servers.slug, slug), gate(p, a, servers))).limit(1),
      update: (slug: string, patch: Partial<ServerRow>) => raw.update(servers).set(patch)
                 .where(and(eq(servers.slug, slug), gate(p, 'manage', servers))).returning(),
      delete: (slug: string) => raw.delete(servers)
                 .where(and(eq(servers.slug, slug), gate(p, 'manage', servers))).returning(),
      create: (row: NewServer) => raw.insert(servers)
                 .values({ ...row, ownerId: p.userId }).returning(),   // owner is never client-supplied
    },
    groups: { /* identical five */ },
    shares: { set: (kind, id, userIds) => /* gate(p,'manage') then replace rows */ },
  }
}
export type ScopedDb = ReturnType<typeof scoped>

import { createCipheriv, createDecipheriv, randomBytes, timingSafeEqual } from 'node:crypto'

/** Envelope: "mcpr.v1.<kid>.<iv_b64u>.<ct_b64u>.<tag_b64u>"  (iv 12B, tag 16B, AES-256-GCM) */
export type Sealed = string & { readonly __sealed: unique symbol }

export function seal(plaintext: string, aad: readonly string[]): Sealed
export function open(sealed: string, aad: readonly string[]): string   // throws SealError
export function isSealed(v: unknown): v is Sealed
export function reseal(sealed: string, aad: readonly string[]): Sealed  // open + seal under active kid
export function activeKid(): string
export class SealError extends Error { constructor(readonly reason: 'no-key'|'unknown-kid'|'auth-failed'|'malformed') {} }

// AAD is the record identity, joined with �. IDs, never names — a rename
// must not brick decryption (mcphub binds [serverName, username],
// credentialBindingService.ts:18-118).
//   env/headers:  ['server', serverId, 'env' | 'headers']
//   upstream oauth: ['upstream-oauth', serverId, userId ?? '-']
//   credential:   ['credential', serverId, userId, slot]

// --- key sourcing ---
// MCPR_SECRET_KEYS="v2:<base64url 32B>,v1:<base64url 32B>"  first entry = active.
// Parsed ONCE at module load. Missing/short/dup-kid -> process.exit(1) with:
//   "MCPR_SECRET_KEYS is not set. Generate one:
//      MCPR_SECRET_KEYS=v1:$(node -e \"…randomBytes(32).toString('base64url')…\")"
// We NEVER auto-create a key file. mcphub's auto-created <settings>.credentials.key
// makes backups silently unrestorable and replicas silently divergent — the same
// failure class as its per-process random JWT_SECRET (config/jwt.ts:4-14).
//
// --- rotation ---
// Prepend a new kid, restart, run `mcpr secrets rotate`: a single transaction per
// table that opens with any known kid and reseals under the active one. Drop the old
// kid from the env once `mcpr secrets status` reports 0 rows on old kids.
//
// --- failure behaviour ---
// open() NEVER returns null or a partial. A server whose secrets fail to open goes
// to status 'error' with reason 'secret_undecryptable' and does not connect —
// never connects with a half-populated env.
//
// --- API surface ---
// Sealed values are never returned by any route. The API returns
// { name, hasValue: boolean } and writes are write-only slots.
//
// ponytail: direct AES-256-GCM under a keyring, not per-record DEKs. Ceiling =
// rotation rewrites every row (fine at 10^4 rows, ~seconds). Upgrade path when
// row counts or an HSM/KMS demand it: keep the envelope string, make <kid> name a
// wrapped DEK column and add one unwrap step inside open().

import { betterAuth } from 'better-auth'
import { drizzleAdapter } from 'better-auth/adapters/drizzle'
import { apiKey, genericOAuth, mcp } from 'better-auth/plugins'
import { hash, verify } from '@node-rs/argon2'

export const auth = betterAuth({
  database: drizzleAdapter(rawForBetterAuth, { provider: 'pg' }),
  secret:  requireEnv('BETTER_AUTH_SECRET'),   // no fallback; boot fails loudly
  baseURL: requireEnv('MCPR_BASE_URL'),
  trustedOrigins: [process.env.MCPR_BASE_URL!],

  emailAndPassword: {
    enabled: true,
    password: { hash: (p) => hash(p), verify: ({ hash: h, password }) => verify(h, password) },
  },
  socialProviders: {
    ...(process.env.GITHUB_CLIENT_ID && { github: { clientId: e('GITHUB_CLIENT_ID'), clientSecret: e('GITHUB_CLIENT_SECRET') } }),
    ...(process.env.GOOGLE_CLIENT_ID && { google: { clientId: e('GOOGLE_CLIENT_ID'), clientSecret: e('GOOGLE_CLIENT_SECRET') } }),
  },

  user: {
    additionalFields: {
      // (1) input:false — without it a signup body can set role:'admin'.
      role:     { type: 'string', defaultValue: 'member', input: false },
      disabled: { type: 'boolean', defaultValue: false,  input: false },
    },
  },
  databaseHooks: {
    user: { create: { before: async (u) => ({ data: {
      ...u, role: (await countUsers()) === 0 ? 'admin' : 'member' } }) } },
    session: { create: { before: async (s) =>
      (await isDisabled(s.userId)) ? false : { data: s } } },
  },

  plugins: [
    ...(process.env.OIDC_ISSUER ? [genericOAuth({ config: [{
      providerId: 'oidc', discoveryUrl: `${e('OIDC_ISSUER')}/.well-known/openid-configuration`,
      clientId: e('OIDC_CLIENT_ID'), clientSecret: e('OIDC_CLIENT_SECRET'), scopes: ['openid','email','profile'],
    }] })] : []),

    apiKey({
      defaultPrefix: 'mcpr_',
      defaultKeyLength: 32,
      enableMetadata: true,                  // carries metadata.grant
      // (2) THE line. Without it a key mints a mock session and an admin's key
      //     becomes an admin principal.
      disableSessionForAPIKeys: true,
      rateLimit: { enabled: true, maxRequests: 600, timeWindow: 60_000 },
      // quota fields (remaining/refillAmount/refillInterval) exist on the plugin;
      // we expose them in the UI but never read them in authz.
    }),

    mcp({
      loginPage: '/login',                   // SPA route; consent is the SPA route /consent
      oidcConfig: {
        requirePKCE: true,
        // (3) DCR stays OFF (better-auth's own default). CIMD is the client
        //     identity mechanism; RFC 7591 is deprecated in the 2026-07-28 spec.
        dynamicClientRegistration: false,
        scopes: ['mcp:list', 'mcp:invoke'],  // fixed vocabulary of TWO.
        //   Per-group authority comes from the RFC 8707 `resource` audience
        //   (https://host/mcp/g/<slug>), which we MUST validate anyway.
      },
    }),
  ],
})

// Mount + the deny-list. 6 lines, a trust boundary.
app.all('/api/auth/api-key/*', (c) => c.notFound())   // keys only via POST /api/keys
app.on(['GET','POST'], '/api/auth/*', (c) => auth.handler(c.req.raw))

import type { OAuthClientProvider } from '@modelcontextprotocol/sdk/client/auth.js'
import { seal, open } from '@mcpr/core'

/** userId=null => a shared service account configured by an admin.
 *  userId set   => per-user tokens; resolution is ALWAYS by principal.userId with
 *  NO fallback to the shared row. mcphub's credentialEligible:false is fail-open by
 *  omission for any new auth path; this is fail-closed by construction. */
export class UpstreamOAuth implements OAuthClientProvider {
  constructor(private serverId: string, private userId: string | null) {}
  private aad = () => ['upstream-oauth', this.serverId, this.userId ?? '-'] as const

  get redirectUrl()    { return new URL('/oauth/callback', BASE_URL).href }
  get clientMetadata() { return {
    client_name: 'MCPRouter', redirect_uris: [this.redirectUrl],
    grant_types: ['authorization_code', 'refresh_token'], response_types: ['code'],
    token_endpoint_auth_method: 'none', scope: 'offline_access',
    client_uri: BASE_URL, software_id: 'mcprouter' } }

  state(): string { /* 32B random, INSERT upstream_oauth_state(serverId,userId,exp=+10m) */ }
  async clientInformation() { const r = await row(); return r && JSON.parse(open(r.clientInfo, this.aad())) }
  async saveClientInformation(i) { await upsert({ clientInfo: seal(JSON.stringify(i), this.aad()) }) }
  async tokens()       { const r = await row(); return r?.tokens && JSON.parse(open(r.tokens, this.aad())) }
  async saveTokens(t)  { await upsert({ tokens: seal(JSON.stringify(t), this.aad()) }) }      // refresh lands here
  async saveCodeVerifier(v) { await updateState({ codeVerifier: seal(v, ['pkce', this.serverId]) }) }
  async codeVerifier() { return open((await state()).codeVerifier, ['pkce', this.serverId]) }
  async invalidateCredentials(s) { /* 'tokens'|'all' -> null the columns, mark server oauth_required */ }

  /** We are server-side: we cannot redirect a browser. Park the URL; the server
   *  row goes to status 'oauth_required' and the UI shows an Authorize button
   *  (keeps mcphub's click-to-authorize affordance, StatusDot). */
  async redirectToAuthorization(url: URL) { await upsert({ authorizeUrl: url.href }) }
}

// Wiring — the SDK does discovery/PKCE/refresh; we add SSRF validation on the
// metadata + authorize + token URLs and on every redirect hop, same as downstream.
const transport = new StreamableHTTPClientTransport(new URL(server.url), {
  authProvider: new UpstreamOAuth(server.id, principal.userId),
  fetch: ssrfGuardedFetch,           // shared with the engine agent's assertSafeUrl
})
// RFC 8707: the SDK sends `resource` = the canonical server URL on BOTH the
// authorize and token requests. We do not hand-roll it.

// GET /oauth/callback handler:
//   1. require a session (SameSite=Lax survives the top-level GET redirect)
//   2. load upstream_oauth_state by ?state=; 404 if absent/expired/used
//   3. assert state.userId === session.user.id            <- CSRF + no cross-user binding
//   4. DELETE the state row (single use), then transport.finishAuth(code)
//   5. 302 to /servers/<slug>  (fixed internal path — never a URL from the query)

